class Solution:
    def myPow(self, x: float, n: int) -> float:
        if n < 0:
            x, n = 1 / x, -n
        result = 1.0
        while n:
            if n & 1:          # this bit of the exponent is set
                result *= x
            x *= x             # x^(2^k) for the next bit
            n >>= 1
        return result

